# %% ../nbs/00_core.ipynb #740e3f87
def motif_occurrences(encoded_library, pattern):
    """Which motifs each sequence contains, as parallel `(sequence index, motif code)` arrays.

    Both strands are scanned and the result is reduced to one entry per sequence per motif, so
    a motif occurring several times in one sequence -- or once on each strand -- is counted
    once. Where a pattern is self-reverse-complementary the two spellings of a site are folded
    onto one code first, so `GAGACC` and `GGTCTC` come back as a single motif rather than two
    rows carrying identical statistics. Windows containing a non-ACGT base, or running off the
    end of a short sequence, are dropped: both carry the out-of-range code that
    `_pattern_window_codes` assigns.

    Returns:
        (seq_idx, motif_codes): equal-length int arrays. `seq_idx` is non-decreasing, so the
        pairs come out grouped by sequence.
    """
    fwd, rc = encoded_library
    n_codes = 4 ** (pattern[0] + pattern[2])
    codes = np.concatenate([_pattern_window_codes(fwd, pattern),
                            _pattern_window_codes(rc, pattern)], axis=1)
    if pattern_is_self_rc(pattern):
        # One site, two spellings, both in this code space -- fold each onto the smaller of the
        # pair. Rejected windows keep their out-of-range code: they are not in the table, so
        # they are held out of the lookup and passed through untouched.
        table = rc_code_table(pattern)
        inside = codes < n_codes
        codes = np.where(inside, np.minimum(codes, table[np.where(inside, codes, 0)]), codes)
    codes.sort(axis=1)                                  # repeats become adjacent
    keep = codes < n_codes                              # drop rejected windows
    keep[:, 1:] &= codes[:, 1:] != codes[:, :-1]        # drop repeats within a sequence
    return np.nonzero(keep)[0], codes[keep]

# %% ../nbs/00_core.ipynb #9444d51e
def _motif_totals(seq_idx, motif_codes, fc_values, background, log2FC_thr, n_codes):
    """Per motif code: sequences carrying it, how many of those are depleted, the sum of their
    log2FC, the sum of their background, and the index of the first sequence that carries it.

    Sums rather than means, because `np.bincount` adds; the means are taken once at the end.
    """
    seq_fc = fc_values[seq_idx]
    n_seqs = np.bincount(motif_codes, minlength=n_codes)
    n_depleted = np.bincount(motif_codes, weights=seq_fc < log2FC_thr, minlength=n_codes)
    fc_sum = np.bincount(motif_codes, weights=seq_fc, minlength=n_codes)
    bg_sum = np.bincount(motif_codes, weights=background[seq_idx], minlength=n_codes)
    first_seq = np.full(n_codes, len(fc_values))
    np.minimum.at(first_seq, motif_codes, seq_idx)
    return n_seqs, n_depleted, fc_sum, bg_sum, first_seq

# %% ../nbs/00_core.ipynb #ec3f32e4
def scan_pattern(encoded_library, pattern, fc_values, background, log2FC_thr=-1, parallel=True):
    """Steps A and B for one pattern: per motif code, how many sequences carry it, how many of
    those are depleted, the sum of their log2FC, the sum of their background, and the first
    sequence that carries it.

    The compiled kernel from `randseq.fast` when numba is installed, `motif_occurrences` and
    `_motif_totals` otherwise -- the same five arrays either way. Every count the pipeline makes
    of "the plasmids carrying a motif" comes from here, so no two steps can disagree on it.
    `background` is each plasmid's expected depletion rate, from `plasmid_background`.
    """
    fc_values = np.asarray(fc_values, dtype=float)
    background = np.asarray(background, dtype=float)
    if _fast.HAVE_NUMBA:
        return _fast.pattern_totals(encoded_library, pattern, fc_values, background, log2FC_thr,
                                    parallel=parallel)
    seq_idx, motif_codes = motif_occurrences(encoded_library, pattern)
    return _motif_totals(seq_idx, motif_codes, fc_values, background, log2FC_thr,
                         4 ** (pattern[0] + pattern[2]))


def _scores_from_totals(totals, pattern, codes):
    """Step C for the given motif codes: the reported statistics, ordered by first sequence."""
    n_seqs, n_depleted, fc_sum, bg_sum, first_seq = totals
    codes = codes[np.argsort(first_seq[codes], kind="stable")]
    n = n_seqs[codes]
    frac = n_depleted[codes] / n
    return pd.DataFrame({
        'motif': decode_motif_codes(codes, pattern),
        'fraction_depleted': frac,
        'num_sequences': n,
        'avg_log2fc': fc_sum[codes] / n,
        # P(at least this many of n depleted | null), the null being the carriers' mean
        # background -- see `plasmid_background` in `01_utils`.
        'p_value': motif_pvalues(n, frac, bg_sum[codes] / n),
    })


def get_pattern_scores(encoded_library, fc_values, pattern, log2FC_thr=-1,
                       background=None, parallel=True):
    """
    Scores every motif of `pattern` found in the library, on both strands.

    Steps A, B and C above: find the (sequence, motif) pairs, total them per motif, and turn
    the totals into the reported statistics. A motif is counted once per sequence that contains
    it on either strand. `tests/reference_scan.py` holds a readable implementation of the same
    scan, and `tests/test_reference_scan.py` requires the two to give identical tables.

    When numba is installed, steps A and B run as one compiled pass instead (`randseq.fast`),
    which returns the same totals; `tests/test_fast_scan.py` requires the two paths to agree.

    Args:
        encoded_library (tuple): (fwd, rc) arrays from `encode_library`.
        fc_values (list or np.ndarray): log2FC of each sequence, in library order.
        pattern (tuple): (d1, spacer, d2) motif pattern.
        log2FC_thr (float): a sequence is depleted when its log2FC is below this value.
        background (np.ndarray): each sequence's expected depletion rate, from
            `plasmid_background`; a motif's p-value is taken against its carriers' mean. Defaults
            to one rate for all, the fraction of this library that is depleted: the encoded
            library holds the sequences with their flanks, not the inserts GC is counted on.
        parallel (bool): let the compiled path use numba's threads. Ignored on the numpy path.

    Returns:
        pd.DataFrame: one row per motif with 'motif', 'fraction_depleted',
            'num_sequences', 'avg_log2fc' and 'p_value', ordered by the first sequence that
            contains the motif.
    """
    fc_values = np.asarray(fc_values, dtype=float)
    if background is None:
        background = np.full(len(fc_values), np.mean(fc_values < log2FC_thr))
    totals = scan_pattern(encoded_library, pattern, fc_values, background, log2FC_thr,
                          parallel)                                                   # A + B
    return _scores_from_totals(totals, pattern, np.flatnonzero(totals[0]))            # C

# %% ../nbs/00_core.ipynb #0b75ece4
def process_single_flexible_pattern(
    current_flex_pattern,
    encoded_library,
    fc_values_for_flexible_analysis,
    background,
    flexible_motif_log2fc_thr,
    flexible_motif_score_thr,
    flexible_motif_min_support,
    parallel=True,
):
    """
    Scores all motifs of one flexible pattern and keeps the candidates with
    fraction_depleted >= flexible_motif_score_thr and num_sequences >= flexible_motif_min_support.

    Args:
        current_flex_pattern (tuple): (d1, spacer, d2) motif pattern.
        encoded_library (tuple): (fwd, rc) arrays from `encode_library` (sequences with context).
        fc_values_for_flexible_analysis (list): log2FC of each sequence, in library order.
        background (np.ndarray): each sequence's expected depletion rate, from
            `plasmid_background`.
        flexible_motif_log2fc_thr (float): log2FC below which a sequence counts as depleted.
        flexible_motif_score_thr (float): minimum fraction_depleted (inclusive, `>=`).
        flexible_motif_min_support (int): minimum number of sequences (inclusive, `>=`).
        parallel (bool): passed to `scan_pattern`; False inside a pool worker.

    Returns:
        (pd.DataFrame, np.ndarray, tuple): the surviving candidates -- 'motif',
            'fraction_depleted', 'num_sequences', 'avg_log2fc', 'p_value' and 'pattern' (the
            pattern as a string) -- the p-value of *every* motif that had enough support to be a
            test, survivor or not, and the pattern's totals from `scan_pattern`, so that later
            steps can look motifs of this pattern up rather than scan it again.

    Both are returned because the Benjamini-Hochberg correction needs the full set of tests, and
    only this function ever sees it: the candidates that fail the score threshold are discarded
    here, but they were still tested, and a correction that ignored them would be wrong.
    """
    fc = np.asarray(fc_values_for_flexible_analysis, dtype=float)
    totals = scan_pattern(encoded_library, current_flex_pattern, fc, background,
                          flexible_motif_log2fc_thr, parallel)
    n_seqs, n_depleted, bg_sum = totals[0], totals[1], totals[3]
    # Only the candidates are turned into strings; the tests stay arrays. A pattern has up to
    # 4**8 motifs present, and decoding every one of them was most of this step's time.
    tested = np.flatnonzero(n_seqs >= max(flexible_motif_min_support, 1))
    frac = n_depleted[tested] / n_seqs[tested]
    kept = _scores_from_totals(totals, current_flex_pattern,
                               tested[frac >= flexible_motif_score_thr])
    kept['pattern'] = str(current_flex_pattern)
    return kept, motif_pvalues(n_seqs[tested], frac, bg_sum[tested] / n_seqs[tested]), totals

# %% ../nbs/00_core.ipynb #b4ea79aa
def variant_profile(motifs, pattern, encoded, fc, background, log2fc_thr, totals=None):
    """Support, depletion score and background for each of a set of related motifs.

    Read off the pattern's totals from `scan_pattern` -- the counts step 2 makes -- so a
    variant is scored exactly as it would have been had its pattern been scanned there.

    Args:
        motifs (list): motif strings, all of the same `pattern`.
        pattern (tuple): the `(d1, spacer, d2)` shape they share.
        encoded (tuple): `(fwd, rc)` from `encode_library`.
        fc (np.ndarray): log2 fold change per library sequence, in the same order.
        background (np.ndarray): each sequence's expected depletion rate, from
            `plasmid_background`.
        log2fc_thr (float): a plasmid is depleted below this.
        totals (dict): totals by canonical pattern, for this library, `fc`, `background` and
            threshold. Shared across calls, it makes every pattern scanned at most once, and the
            patterns step 2 scanned never again. Filled in place.

    Returns:
        list: one `(motif, n_plasmids, score, background)` per motif, in the order given, the
        background being the carriers' mean. A motif that has no code (an IUPAC base, or a
        defined base in the spacer) gets `n=0` and `nan` for the other two.
    """
    totals = {} if totals is None else totals
    canon = canonical_pattern(pattern)
    if canon not in totals:
        totals[canon] = scan_pattern(encoded, canon, fc, background, log2fc_thr)
    n_seqs, n_depleted, _, bg_sum, _ = totals[canon]
    mirrored = pattern[1] != 0 and tuple(pattern) != canon    # spelled on the other strand
    rc_table = rc_code_table(canon) if pattern_is_self_rc(canon) else None
    out = []
    for m in motifs:
        code = encode_motif(revcomp(m) if mirrored else m, canon)
        if code is not None and rc_table is not None:
            code = min(code, int(rc_table[code]))             # the fold step 2 applied
        n = int(n_seqs[code]) if code is not None else 0
        out.append((m, n, float(n_depleted[code] / n) if n else float("nan"),
                    float(bg_sum[code] / n) if n else float("nan")))
    return out

# %% ../nbs/00_core.ipynb #f0204ef3
def verdict(profile, score_thr, min_support):
    """Call a variant profile 'mixture', 'genuine' or 'unknown'.

    Args:
        profile (list): `(motif, n, score, ...)` from `variant_profile`; only `n` and `score`
            are read.
        score_thr (float): the depletion score a candidate had to reach to be here.
        min_support (int): a variant on fewer plasmids than this is not judged.

    Returns:
        tuple: the verdict, and the spread across judgeable variants (`None` when fewer than
        two can be judged).
    """
    judged = [p[2] for p in profile if p[1] >= min_support]
    if len(judged) < 2:
        return "unknown", None
    spread = max(judged) - min(judged)
    split = any(s < score_thr for s in judged) and spread >= score_thr
    return ("mixture" if split else "genuine"), spread

# %% ../nbs/00_core.ipynb #a7b0c0fa
def _undefined_positions(motif, pattern):
    """Each undefined position worth testing on a candidate, as (four variants, their pattern)."""
    d1, spacer, d2 = pattern
    width = d1 + spacer + d2
    jobs = [([b + motif for b in "ACGT"], (width + 1, 0, 0) if spacer == 0 else (d1 + 1, spacer, d2)),
            ([motif + b for b in "ACGT"], (width + 1, 0, 0) if spacer == 0 else (d1, spacer, d2 + 1))]
    if spacer:
        p = d1
        jobs.append(([motif[:p] + b + motif[p + 1:] for b in "ACGT"],
                     (d1 + 1 + d2, 0, 0) if spacer == 1 else (d1 + 1, spacer - 1, d2)))
        if spacer > 1:
            p = d1 + spacer - 1
            jobs.append(([motif[:p] + b + motif[p + 1:] for b in "ACGT"], (d1, spacer - 1, d2 + 1)))
    return jobs

# %% ../nbs/00_core.ipynb #b04daf67
def is_mixture(motif, pattern, encoded_library, fc_values, background, log2fc_thr=-1,
               score_thr=0.5, min_support=5, totals=None):
    """Does fixing one position next to this motif split its carriers into sites and non-sites?

    Args:
        motif (str): the candidate.
        pattern (tuple): its `(d1, spacer, d2)` shape.
        encoded_library (tuple): `(fwd, rc)` from `encode_library`.
        fc_values (np.ndarray): log2 fold change per library sequence.
        background (np.ndarray): each sequence's expected depletion rate, from
            `plasmid_background`. The verdict compares the variants with each other and does not
            read it; it completes the totals of a pattern scanned here, which rule 3 shares.
        log2fc_thr (float), score_thr (float), min_support (int): as elsewhere in the step.
        totals (dict): shared pattern totals, as for `variant_profile`.

    Returns:
        bool: True when some position's four bases split.
    """
    for variants, vpat in _undefined_positions(motif, pattern):
        if sum(vpat) > encoded_library[0].shape[1]:  # the padded motif is wider than the insert
            continue
        if verdict(variant_profile(variants, vpat, encoded_library, fc_values, background,
                                   log2fc_thr, totals), score_thr, min_support)[0] == "mixture":
            return True
    return False

# %% ../nbs/00_core.ipynb #7b72c066
def is_extension(specific, general):
    """Is `specific` the motif `general` with one more defined base, on either strand?

    The extra base sits one past an end of `general` or at an edge of its spacer -- the
    positions `_undefined_positions` tests. Both strands are checked because every pattern is
    searched in one canonical form, so adding a base to a motif's longer side can turn its shape
    into the mirror form, which the scan writes on the other strand: `TACNNNNGTGA` is
    `CACNNNNGTA` with a base added on the left.
    """
    defined = lambda m: len(m) - m.count("N")
    return defined(specific) == defined(general) + 1 and find_broad_in_specific(specific, general)

# %% ../nbs/00_core.ipynb #c910b1f7
def motif_shape(motif):
    """`(trimmed motif, pattern)`, or None when the string is not a `(d1, spacer, d2)` motif.

    Leading and trailing `N` are not part of a motif, and a string with two gaps is not a shape
    any pattern can express.
    """
    motif = motif.strip("N")
    if not motif:
        return None
    runs = re.findall(r"N+|[^N]+", motif)
    if len(runs) == 1:
        return motif, (len(motif), 0, 0)
    if len(runs) == 3:
        return motif, (len(runs[0]), len(runs[1]), len(runs[2]))
    return None


def parent_motifs(motif, pattern):
    """Every motif `motif` could be a one-base extension of.

    The inverse of `_undefined_positions`: the base it adds sits at an end or at a spacer edge,
    so giving up one of those four bases recovers the motif it extends. Checking these against
    the candidates is the same question as `is_extension` against every shorter candidate, at a
    handful of lookups instead of a comparison per pair.

    Returns the motif strings, without their patterns -- a caller matching against a set of
    candidate strings does not need them.
    """
    d1, spacer, d2 = pattern
    raw = [motif[1:], motif[:-1]]
    if spacer:
        raw.append(motif[:d1 - 1] + "N" + motif[d1:])                  # widen the gap leftwards
        raw.append(motif[:d1 + spacer] + "N" + motif[d1 + spacer + 1:])  # ... and rightwards
    out = []
    for s in raw:
        shaped = motif_shape(s)
        if shaped is not None and shaped[0] != motif:
            out.append(shaped[0])
    return sorted(set(out))

# %% ../nbs/00_core.ipynb #ed02ec03
def relax_positions(motif, pattern):
    """The defined bases of `motif` that can be put back to N, leaving a valid pattern.

    Every base of a contiguous motif -- an interior one becomes a one-base spacer -- and, for a
    gapped motif, the outer base and the spacer-side base of each half, as long as the half keeps
    a defined base. These are the positions rule 1 tests from the other side.
    """
    d1, spacer, d2 = pattern
    if spacer == 0:
        return list(range(len(motif)))
    positions = set()
    if d1 >= 2:
        positions |= {0, d1 - 1}
    if d2 >= 2:
        positions |= {d1 + spacer, len(motif) - 1}
    return sorted(positions)


LR_THRESHOLD = 10   # a set of plasmids is classified when one model fits it this many times better


def site_or_background(n, k, site_rate, background_rate):
    """'site', 'non-site' or 'unknown' for a set of `n` plasmids of which `k` are depleted.

    Compares two models of them -- depleted at `site_rate`, or at `background_rate` -- by their
    log-likelihood ratio, which grows with `n`, so it is also the confidence: the set is
    classified only when one model fits `LR_THRESHOLD` times better. Rates must lie strictly
    between 0 and 1; a site rate no higher than background gives 'unknown'.
    """
    if site_rate <= background_rate:
        return "unknown"
    llr = (k * np.log(site_rate / background_rate)
           + (n - k) * np.log((1 - site_rate) / (1 - background_rate)))
    cut = np.log(LR_THRESHOLD)
    return "site" if llr > cut else "non-site" if llr < -cut else "unknown"


def classify_bases(profile, motif, min_support):
    """'site', 'non-site' or 'unknown' for each base other than `motif`'s at one position.

    Each base's carriers are compared under two models -- depleted at the site's rate, or at
    their own background -- by their log-likelihood ratio. The site's rate is the candidate's
    own, re-estimated once from the candidate pooled with the bases first classified site-like.

    Args:
        profile (list): `(motif, n, score, background)` for the four bases, from
            `variant_profile`.
        motif (str): the candidate, one of the four.
        min_support (int): a base carried by fewer plasmids is not classified.

    Returns:
        dict: other motif -> class, for those with at least `min_support` carriers; `None` when
        the candidate itself has too few.
    """
    own = next((p for p in profile if p[0] == motif), None)
    if own is None or own[1] < min_support:
        return None
    others = [p for p in profile if p[0] != motif and p[1] >= min_support]
    clip = lambda rate, n: min(max(rate, 0.5 / n), 1 - 0.5 / n)   # keep the logs finite

    def classify(site_rate):
        return {m: site_or_background(n, round(s * n), site_rate, b) for m, n, s, b in others}

    first = classify(clip(own[2], own[1]))
    pooled = [own] + [p for p in others if first[p[0]] == "site"]
    n = sum(p[1] for p in pooled)
    return classify(clip(sum(p[1] * p[2] for p in pooled) / n, n))


def classify_positions(motif, positions, pattern, encoded_library, fc_values, background,
                       log2fc_thr=-1, min_support=5, totals=None):
    """For each position, the class and carriers of every base `motif` does not allow there.

    At position `i`, each base `motif` does not allow gives a variant -- `motif` with that base at
    `i` -- and `classify_bases` classifies it against `motif`. A motif of A, C, G and T is profiled
    from the scan's counts (`variant_profile`); a motif with an IUPAC letter is profiled on the
    carriers of its instances (`_union_profile`).

    Args:
        motif (str): the candidate, IUPAC letters allowed at its defined positions.
        positions (list): defined positions of `motif` to classify.
        pattern (tuple): its `(d1, spacer, d2)` shape.
        encoded_library, fc_values, background, log2fc_thr, min_support, totals: as for
            `is_mixture`.

    Returns:
        dict: position -> {base: (class, n carriers)}, for the bases with at least `min_support`
        carriers; empty at every position when `motif` itself has fewer.
    """
    alts = {i: [motif[:i] + b + motif[i + 1:] for b in "ACGT" if b not in IUPAC_EXPAND[motif[i]]]
            for i in positions}
    motifs = [motif] + [v for vs in alts.values() for v in vs]
    if encode_motif(motif, pattern) is not None:          # A, C, G and T only: the scan's counts
        profile = variant_profile(motifs, pattern, encoded_library, fc_values, background,
                                  log2fc_thr, totals)
    else:
        profile = _union_profile(motifs, pattern, encoded_library, fc_values, background,
                                 log2fc_thr)
    stats = dict(zip(motifs, profile))
    out = {}
    for i, vs in alts.items():
        classes = classify_bases([profile[0]] + [stats[v] for v in vs], motif, min_support) or {}
        out[i] = {v[i]: (classes[v], stats[v][1]) for v in vs if v in classes}
    return out


def is_over_specified(motif, pattern, encoded_library, fc_values, background, log2fc_thr=-1,
                      min_support=5, totals=None):
    """Does `motif` have a defined base at which every other base behaves like the site?"""
    by_position = classify_positions(motif, relax_positions(motif, pattern), pattern,
                                     encoded_library, fc_values, background, log2fc_thr,
                                     min_support, totals)
    return any(classes and all(c == "site" for c, _ in classes.values())
               for classes in by_position.values())

# %% ../nbs/00_core.ipynb #dd9f3316
def _patterns(df):
    """The 'pattern' column as `(d1, spacer, d2)` tuples; None where it is missing or unreadable."""
    if "pattern" not in df.columns:
        return [None] * len(df)
    out = []
    for p in df["pattern"]:
        try:
            out.append(tuple(ast.literal_eval(p) if isinstance(p, str) else p) or None)
        except (ValueError, SyntaxError, TypeError):
            out.append(None)
    return out


def motif_instances(motif, pattern):
    """The motifs of A, C, G and T that `motif` stands for: every IUPAC letter at a defined position
    expanded, the spacer left as it is."""
    d1, spacer, _ = pattern
    gap = range(d1, d1 + spacer)
    choices = [c if i in gap else sorted(IUPAC_EXPAND[c]) for i, c in enumerate(motif)]
    return ["".join(t) for t in product(*choices)]


def _instance_presence(encoded, motifs, patterns):
    """`motif_presence_matrix` for motifs with IUPAC letters: a plasmid carries a motif when it
    carries one of its instances (`motif_instances`), on either strand. Returns `(matrix, handled)`;
    a motif whose pattern is unknown, or which does not fit it, is not handled."""
    inst = [motif_instances(m, p) if p is not None else [] for m, p in zip(motifs, patterns)]
    # Each distinct instance is looked up once, however many motifs share it.
    keys = list(dict.fromkeys((x, p) for xs, p in zip(inst, patterns) for x in xs))
    col = {k: j for j, k in enumerate(keys)}
    has, ok = motif_presence_matrix(encoded, [x for x, _ in keys], [p for _, p in keys])
    presence = np.zeros((encoded[0].shape[0], len(motifs)), dtype=bool)
    handled = np.zeros(len(motifs), dtype=bool)
    for j, (xs, p) in enumerate(zip(inst, patterns)):
        cols = [col[(x, p)] for x in xs]
        if cols and ok[cols].all():
            presence[:, j] = has[:, cols].any(axis=1)
            handled[j] = True
    return presence, handled


def _carriers(encoded, motifs, patterns, log2fc_series, left_context, right_context):
    """Boolean (n_sequences, n_motifs): which plasmids carry each motif, on either strand.

    Read from the window codes of each motif's instances (`_instance_presence`); a motif whose
    pattern is unknown falls back to a regex over the sequences with their flanks.
    """
    presence, handled = _instance_presence(encoded, motifs, patterns)
    for j in np.flatnonzero(~handled):
        presence[:, j] = _get_filter_for_motif(
            log2fc_series, motifs[j], left_context, right_context).to_numpy()
    return presence

# %% ../nbs/00_core.ipynb #8bc15550
def filter_redundant_patterns(df, log2fc_series, left_context, right_context,
                              log2fc_thr=-1, score_thr=0.5, min_support=5,
                              encoded=None, totals=None, background=None):
    """Keep one description per site, by three rules.

    1. **A mixture is not a site.** A candidate is dropped when fixing one position next to it
       splits the plasmids that carry it into depleting and not (`is_mixture`).
    2. **A one-base extension of a site is redundant.** A candidate is dropped when it is a
       candidate that survived rule 1 with one more defined base (`is_extension`, applied by
       looking up `parent_motifs`): rule 1 found that site's neighbouring positions carry
       nothing, so pinning one adds nothing.
    3. **A motif with an uninformative base is not the site.** A candidate is dropped when, at one
       of its defined bases, every other base behaves like the site (`is_over_specified`).

    No rule depends on the order the candidates arrive in.

    Args:
        df (pd.DataFrame): candidates, with 'motif' and 'pattern'.
        log2fc_series (pd.Series): log2 fold change, indexed by insert sequence.
        left_context (str), right_context (str): the vector flanks.
        log2fc_thr (float): a plasmid is depleted below this.
        score_thr (float): the score a candidate had to reach, reused as the bar a variant must
            clear and as the spread that marks a profile a mixture.
        min_support (int): a variant on fewer plasmids than this is not judged.
        encoded (tuple): the library from `encode_library`, if the caller already has it.
        totals (dict): shared pattern totals, as for `variant_profile`.
        background (np.ndarray): each plasmid's expected depletion rate; `plasmid_background` of
            `log2fc_series` when not given.

    Returns:
        pd.DataFrame: `df` without the redundant rows, in the original row order.
    """
    if df.empty:
        return df
    motifs = df["motif"].tolist()
    pats = _patterns(df)
    if encoded is None:
        encoded = encode_library(get_lib_seq_context(log2fc_series.index.tolist(),
                                                     left_context, right_context))
    totals = {} if totals is None else totals
    fc = log2fc_series.to_numpy()
    if background is None:
        background = plasmid_background(log2fc_series.index, fc, log2fc_thr)

    # Rule 1. A candidate whose pattern is unknown cannot be tested, and stays.
    survivors = [k for k in range(len(df)) if pats[k] is None or not is_mixture(
        motifs[k], pats[k], encoded, fc, background, log2fc_thr, score_thr, min_support, totals)]

    # Rule 2, by lookup rather than by comparing pairs: each survivor asks whether any of the
    # four motifs it could extend is itself a survivor. Comparing every pair is quadratic, and
    # at a permissive threshold a strain can reach hundreds of thousands of candidates.
    standing = {motifs[k] for k in survivors}
    standing |= {revcomp(m) for m in standing}      # a parent may be spelled on the other strand
    keep = [k for k in survivors
            if not any(g in standing for g in parent_motifs(motifs[k], pats[k]))]

    # Rule 3. Every variant it reads is in the candidate's own pattern, which step 2 counted.
    keep = [k for k in keep if pats[k] is None or not is_over_specified(
        motifs[k], pats[k], encoded, fc, background, log2fc_thr, min_support, totals)]
    return df.iloc[keep]

