def filter_explained_candidates(candidates_df, log2fc_series, left_context, right_context,
                                log2fc_thr=-1, score_thr=0.7, min_support=3,
                                encoded=None, p_threshold=0.05, background=None):
    """Drop candidates whose depletion is fully accounted for by stronger candidates.

    Candidates are taken strongest first. Each `X` is restricted to the plasmids that carry
    **none** of the stronger candidates still standing; if what is left no longer reaches
    `score_thr`, or is not depleted beyond its own background at `p_threshold`, `X`'s score
    was borrowed and `X` is removed. Otherwise it stands, and the plasmids that carry it join the
    set later candidates are tested against.

    After the pass, every survivor is tested again against the union of *all* the others,
    weakest first, removing one at a time: the pass tests a candidate only against those ranked
    above it, and a shadow can rank above the site it shadows.

    Args:
        candidates_df: candidates, with 'motif' and (optionally) 'pattern' columns.
        log2fc_series: the full log2FC series, indexed by sequence.
        left_context, right_context: the vector sequence flanking the insert.
        log2fc_thr: a plasmid is depleted below this.
        score_thr: fraction of a candidate's leftover plasmids that must still be depleted.
        min_support: not used: a candidate's support was established when it became one.
            Accepted so the step takes the same thresholds as the rest of the pipeline.
        encoded: the library from `encode_library`, if the caller already has it.
        p_threshold: the leftover must also be depleted beyond its background -- the mean
            background of its plasmids -- at this p-value. `find_restricted_motifs` passes the
            scan's Benjamini-Hochberg cutoff.
        background: each plasmid's expected depletion rate; `plasmid_background` of
            `log2fc_series` when not given.

    Returns:
        (kept_df, explanations) where explanations maps a dropped motif to
        (explaining motif, plasmids left, score on them).
    """
    if len(candidates_df) < 2:
        return candidates_df, {}     # nothing that could explain anything

    motifs = candidates_df['motif'].tolist()
    if encoded is None:
        encoded = encode_library(
            get_lib_seq_context(log2fc_series.index.tolist(), left_context, right_context))
    presence = _carriers(encoded, motifs, _patterns(candidates_df), log2fc_series,
                         left_context, right_context)

    fc = log2fc_series.to_numpy()
    if background is None:
        background = plasmid_background(log2fc_series.index, fc, log2fc_thr)
    strength = []
    for j in range(len(motifs)):
        v = fc[presence[:, j]]
        strength.append(((v < log2fc_thr).mean() if len(v) else 0.0, len(v), motifs[j]))
    # Strongest first: highest depletion fraction, then MOST plasmids. Support breaks the tie, not
    # mean log2FC, because the plasmids carrying a shadow are a subset of those carrying its
    # parent, and the subset picked out by the extra bases it requires tends to be the most
    # depleted -- so on mean log2FC a shadow outranks the site it came from and is never tested
    # against it. A subset can never have more plasmids than the set it is drawn from. The motif
    # string is the final tie-break, so the outcome does not depend on row order.
    order = sorted(range(len(motifs)), key=lambda j: (-strength[j][0], -strength[j][1], strength[j][2]))

    # A leftover stands when it still reaches score_thr AND is depleted beyond its own
    # background -- the binomial null the calls are scored against, the rate being the mean
    # background of the leftover plasmids -- at the scan's own cutoff.
    def holds(alone):
        n = int(alone.sum())
        still = float((fc[alone] < log2fc_thr).mean()) if n else 0.0
        ok = n > 0 and still >= score_thr and \
            motif_pvalues([n], [still], background[alone].sum() / n)[0] <= p_threshold
        return ok, n, still

    explanations = {}
    # The test is against the UNION of the stronger survivors: a description that overlaps
    # several co-occurring sites can keep a depleted residue against each of them separately
    # although every plasmid that carries it carries one of them.
    covered = np.zeros(presence.shape[0], dtype=bool)
    standing = []                                        # survivors, strongest first
    for x in order:
        ok, n, still = holds(presence[:, x] & ~covered)
        if not ok:
            # Name the survivor that accounts for most of X's plasmids, and say how many others
            # it took. A dropped candidate explains nothing, so it never joins `covered`.
            shared = [(int((presence[:, x] & presence[:, y]).sum()), -k, y)
                      for k, y in enumerate(standing)]
            shared = [s for s in shared if s[0] > 0]
            if shared:
                label = motifs[max(shared)[2]] + (
                    f" + {len(shared) - 1} more" if len(shared) > 1 else "")
            else:                    # fails on the plasmids that carry it; nothing to blame
                label = "(no stronger motif)"
            explanations[x] = (label, n, still)
            continue
        covered |= presence[:, x]
        standing.append(x)

    # The audit: every survivor against all the others, weakest first, one removal at a time.
    survivors = standing
    while len(survivors) > 1:
        cover = presence[:, survivors].sum(axis=1)
        for x in sorted(survivors, key=lambda j: strength[j]):
            ok, n, still = holds(presence[:, x] & (cover == 1))   # carried by x alone
            if not ok:
                overlap = max((y for y in survivors if y != x),
                              key=lambda y: int((presence[:, x] & presence[:, y]).sum()))
                explanations[x] = (motifs[overlap] + " (audit)", n, still)
                survivors.remove(x)
                break
        else:
            break

    keep = [j for j in range(len(motifs)) if j not in explanations]
    return candidates_df.iloc[keep], {motifs[x]: v for x, v in explanations.items()}

# %% ../nbs/00_core.ipynb #006a8b89
def _canonicalise_flexible_motifs(df):
    """Put every motif in a flexible-motif result table on its canonical strand.

    A motif and its reverse complement have identical statistics, so rewriting the label loses
    nothing.
    """
    if df is None or df.empty or 'motif' not in df.columns:
        return df
    df = df.copy()
    flipped = df['motif'] != df['motif'].map(canonical_motif)
    df['motif'] = df['motif'].map(canonical_motif)
    # The pattern has to follow the motif. Reverse-complementing a (d1, spacer, d2) site gives
    # a (d2, spacer, d1) site, so a relabelled row whose pattern was left alone would describe
    # a string it does not hold -- and every consumer that pairs motif with pattern, such as
    # motif_presence_matrix, would silently decline to handle it.
    if 'pattern' in df.columns:
        def _mirror(p):
            try:
                d1, sp, d2 = ast.literal_eval(p) if isinstance(p, str) else tuple(p)
            except (ValueError, SyntaxError, TypeError):
                return p
            # With no spacer the site is contiguous and (k, 0, 0) is the spelling the
            # pattern list uses, so mirroring must not turn (6, 0, 0) into (0, 0, 6).
            m = (d1 + d2, 0, 0) if sp == 0 else (d2, sp, d1)
            return str(m) if isinstance(p, str) else m
        df.loc[flipped, 'pattern'] = df.loc[flipped, 'pattern'].map(_mirror)
    return df

# %% ../nbs/00_core.ipynb #f9ba37dc
def bimodality_coefficient(values):
    """Sarle's bimodality coefficient: (skew^2 + 1) / (kurtosis + 3(n-1)^2/((n-2)(n-3))).

    Above 5/9 the distribution is more bimodal than a uniform one. NaN below four values, where
    it is not defined, and when every value is the same.
    """
    v = np.asarray(values, dtype=float)
    v = v[np.isfinite(v)]
    n = len(v)
    if n < 4 or np.allclose(v, v[0]):
        return float("nan")
    g = skew(v, bias=False)
    k = kurtosis(v, bias=False, fisher=True)
    denom = k + 3.0 * (n - 1) ** 2 / ((n - 2) * (n - 3))
    return float((g ** 2 + 1.0) / denom) if denom > 0 else float("nan")


BIMODALITY_BENCHMARK = 5.0 / 9.0


def upper_group_median(values):
    """Median of the upper group when `values` are split in two at the cut that maximises the
    between-group variance (Otsu's method: two-means in one dimension, on the sorted values).

    NaN below two finite values.
    """
    v = np.sort(np.asarray(values, dtype=float))
    v = v[np.isfinite(v)]
    n = len(v)
    if n < 2:
        return float("nan")
    k = np.arange(1, n)                       # the lower group is v[:k]
    low = np.cumsum(v)[:-1]
    between = k * (n - k) * (low / k - (v.sum() - low) / (n - k)) ** 2
    return float(np.median(v[k[np.argmax(between)]:]))


def annotate_significance(results_df, log2fc_series, left_context, right_context,
                          all_pvalues=None, log2fc_thr=-1, q_threshold=0.05, encoded=None,
                          background=None, score_thr=0.5):
    """Add fraction_depleted_lower, background, excess_depleted, p_value, q_value, called,
    bimodality and bimodal to a result table.

    `fraction_depleted_lower` is the one-sided lower confidence bound on the fraction of carriers
    depleted (Clopper-Pearson, at level `q_threshold`). A candidate had to reach `score_thr` --
    most of its carriers depleted -- and a call has to show it: 5 of 10 depleted is 0.5, but its
    bound is 0.22.

    `background` is the rate at which the motif's carriers would deplete with no site involved:
    the mean over them of each plasmid's GC-matched background (`plasmid_background`, computed
    from `log2fc_series` when not given). The p-value is taken against it, as in the scan.
    `excess_depleted` is the fraction of carriers depleted beyond it,
    (fraction_depleted - background) / (1 - background): 0 when carriers deplete no more than
    plasmids like them, 1 when every one is destroyed. It measures how strong the effect is; q
    measures how sure we are of it.

    `all_pvalues` are the p-values of every motif the scan tested, which is what the
    Benjamini-Hochberg correction has to be computed over -- correcting only over the handful
    that survived filtering would be meaningless.

    `bimodal` marks carriers that are a mixture of depleted and background-level plasmids: a
    bimodality coefficient above 5/9 and an upper group (`upper_group_median`) that is not
    depleted at `log2fc_thr`.

    Nothing is removed. `called` marks the rows whose q-value is below `q_threshold` and whose
    `fraction_depleted_lower` reaches `score_thr`; the rest stay in the table so that a weak
    result is visible as a weak claim rather than silently absent.
    """
    if results_df is None:
        return results_df
    if results_df.empty:
        # A strain with no active system is the first thing a new user runs, so the empty
        # table must have the same columns as a full one -- otherwise `flex[flex.called]`
        # works on every strain that finds something and raises on the ones that do not.
        out = results_df.copy()
        for _c, _dt in (("fraction_depleted_lower", float), ("background", float),
                        ("excess_depleted", float), ("p_value", float),
                        ("q_value", float), ("called", bool), ("bimodality", float),
                        ("bimodal", bool)):
            if _c not in out.columns:
                out[_c] = pd.Series(dtype=_dt)
        return out
    # Placed beside fraction_depleted below; dropped first so a table can be annotated again.
    out = results_df.drop(columns=["fraction_depleted_lower", "background", "excess_depleted"],
                          errors="ignore")
    if encoded is None:
        encoded = encode_library(
            get_lib_seq_context(log2fc_series.index.tolist(), left_context, right_context))
    if background is None:
        background = plasmid_background(log2fc_series.index, log2fc_series.to_numpy(), log2fc_thr)
    presence = _carriers(encoded, out["motif"].tolist(), _patterns(out), log2fc_series,
                         left_context, right_context)
    # Each motif's null is its carriers' mean background, summed exactly as the scan sums it, so
    # that a reported motif's p-value is the scan's to the last bit (see `plasmid_background`).
    rate = (background @ presence) / presence.sum(axis=0)
    n = out["num_sequences"].to_numpy()
    k = np.rint(out["fraction_depleted"].to_numpy() * n)
    at = out.columns.get_loc("fraction_depleted") + 1
    out.insert(at, "fraction_depleted_lower",
               np.where(k > 0, beta.ppf(q_threshold, np.maximum(k, 1), n - k + 1), 0.0))
    out.insert(at + 1, "background", rate)
    out.insert(at + 2, "excess_depleted", (out["fraction_depleted"] - rate) / (1 - rate))

    p = motif_pvalues(out["num_sequences"].to_numpy(), out["fraction_depleted"].to_numpy(), rate)
    out["p_value"] = p
    if all_pvalues is not None and len(all_pvalues):
        # The reported motifs were tested by the scan, so their p-values are already in
        # `all_pvalues`; appending them again counted those tests twice. Only a p-value the scan
        # never produced is a new test and joins the pool. Each motif's q is then read off the
        # adjusted pool at its own p-value -- BH q-values are a non-decreasing step function of
        # p, so tied p-values share one q.
        pool = np.asarray(all_pvalues, dtype=float)
        pool = np.sort(np.concatenate([pool, p[~np.isin(p, pool)]]))
        q_pool = benjamini_hochberg(pool)
        out["q_value"] = q_pool[np.searchsorted(pool, p, side="right") - 1]
    else:
        out["q_value"] = benjamini_hochberg(p)
    out["called"] = (out["q_value"] < q_threshold) & (out["fraction_depleted_lower"] >= score_thr)

    values = log2fc_series.to_numpy()
    carriers = [values[presence[:, j]] for j in range(len(out))]
    out["bimodality"] = [bimodality_coefficient(v) for v in carriers]
    # Two modes, the upper one at background: destroyed and untouched plasmids mixed. Two
    # depleted modes -- strong and very strong -- are a site, not a mixture.
    out["bimodal"] = (out["bimodality"] > BIMODALITY_BENCHMARK) & \
        np.array([upper_group_median(v) >= log2fc_thr for v in carriers], dtype=bool)

    return out.sort_values(["called", "q_value"], ascending=[False, True])

# %% ../nbs/00_core.ipynb #8fd90aec
def _union_profile(motifs, pattern, encoded, fc, background, log2fc_thr):
    """`variant_profile` for motifs with IUPAC letters: each scored on the plasmids carrying any of
    its instances, which the scan's per-motif counts cannot give (a plasmid can carry two)."""
    has = _instance_presence(encoded, motifs, [pattern] * len(motifs))[0]
    n = has.sum(axis=0)
    depleted = (fc < log2fc_thr).astype(float) @ has
    bg_sum = background @ has
    return [(m, int(k), float(d / k) if k else float("nan"), float(b / k) if k else float("nan"))
            for m, k, d, b in zip(motifs, n, depleted, bg_sum)]


def generalise_motif(motif, pattern, encoded_library, fc_values, background, log2fc_thr=-1,
                     min_support=5, totals=None):
    """`motif` with each degenerate position written as the IUPAC letter of its site-like bases.

    At every defined position the bases `motif` does not allow are classified
    (`classify_positions`). Where some, but not all, are site-like, they join the bases allowed
    there. One position changes at a time -- the one whose site-like bases have the most carriers,
    the first on a tie -- and the merged motif is classified again, on its own carriers, until no
    position changes.

    Args:
        motif (str): a called motif.
        pattern (tuple): its `(d1, spacer, d2)` shape.
        encoded_library, fc_values, background, log2fc_thr, min_support, totals: as for
            `is_mixture`.

    Returns:
        str: the merged motif, or `motif` itself when no position is degenerate.
    """
    defined = [i for i, c in enumerate(motif) if c != "N"]
    while True:
        best = None
        for i, classes in classify_positions(motif, defined, pattern, encoded_library, fc_values,
                                             background, log2fc_thr, min_support, totals).items():
            site = [b for b, (c, _) in classes.items() if c == "site"]
            # Every other base site-like is an uninformative base (rule 3), not a degenerate one.
            if site and len(site) < len(classes):
                n = sum(classes[b][1] for b in site)
                if best is None or n > best[0]:
                    best = (n, i, site)
        if best is None:
            return motif
        _, i, site = best
        motif = motif[:i] + IUPAC_COLLAPSE[IUPAC_EXPAND[motif[i]] | frozenset(site)] + motif[i + 1:]

# %% ../nbs/00_core.ipynb #fcb77d69
def _is_instance(specific, general):
    """Does `general` allow every base of `specific`, on one strand or the other?"""
    allows = lambda s: len(s) == len(general) and all(
        IUPAC_EXPAND[a] <= IUPAC_EXPAND[b] for a, b in zip(s, general))
    return allows(specific) or allows(revcomp(specific))


def _motif_rows(motifs, patterns, log2fc_series, left_context, right_context, encoded, log2fc_thr):
    """Result-table rows -- support, fraction depleted, mean log2FC, pattern -- read off each
    motif's carriers."""
    has = _carriers(encoded, motifs, patterns, log2fc_series, left_context, right_context)
    fc = log2fc_series.to_numpy(dtype=float)
    n = has.sum(axis=0)
    return pd.DataFrame({"motif": motifs,
                         "fraction_depleted": (fc < log2fc_thr).astype(float) @ has / n,
                         "num_sequences": n, "avg_log2fc": fc @ has / n,
                         "pattern": [str(p) for p in patterns]})


def merge_degenerate_calls(table, log2fc_series, left_context, right_context, encoded, background,
                           all_pvalues, log2fc_thr=-1, q_threshold=0.05, score_thr=0.5,
                           min_support=5, totals=None):
    """Report each degenerate site as one IUPAC motif, in place of its called variants.

    Every called row is generalised (`generalise_motif`); each distinct merged motif that is not an
    instance of another is scored on its own carriers (`annotate_significance`, against
    `all_pvalues`). A called merged motif replaces the called rows that are instances of it.

    Args:
        table (pd.DataFrame): the scored result table, from `annotate_significance`.
        log2fc_series (pd.Series): log2 fold change, indexed by insert sequence, as scored.
        left_context (str), right_context (str): the vector flanks.
        encoded (tuple): the library from `encode_library`.
        background (np.ndarray): each plasmid's expected depletion rate.
        all_pvalues (np.ndarray): the p-values of every motif the scan tested.
        log2fc_thr, q_threshold, score_thr: as for `annotate_significance`.
        min_support (int), totals (dict): as for `classify_positions`.

    Returns:
        pd.DataFrame: `table` with a 'merged_from' column -- the replaced motifs joined by '+', empty
        for every other row -- and the merged rows in place of those they replaced, called rows
        first. A table with no merge comes back as it was, with the column added.
    """
    table = table.assign(merged_from="")
    called = table[table["called"]]
    fc = log2fc_series.to_numpy(dtype=float)
    totals = {} if totals is None else totals
    grown = {}                                       # canonical merged motif -> (spelling, pattern)
    for motif, pattern in zip(called["motif"], _patterns(called)):
        merged = generalise_motif(motif, pattern, encoded, fc, background, log2fc_thr,
                                  min_support, totals)
        if merged != motif:
            grown.setdefault(canonical_motif(merged), (merged, pattern))
    keep = [m for m in grown if not any(o != m and _is_instance(m, o) for o in grown)]
    if not keep:
        return table
    rows = _motif_rows([grown[m][0] for m in keep], [grown[m][1] for m in keep], log2fc_series,
                       left_context, right_context, encoded, log2fc_thr)
    scored = annotate_significance(_canonicalise_flexible_motifs(rows), log2fc_series, left_context,
                                   right_context, all_pvalues=all_pvalues, log2fc_thr=log2fc_thr,
                                   q_threshold=q_threshold, encoded=encoded,
                                   background=background, score_thr=score_thr)
    scored = scored[scored["called"]]
    if scored.empty:
        return table
    absorbed = [[m for m in called["motif"] if _is_instance(m, g)] for g in scored["motif"]]
    scored = scored.assign(merged_from=["+".join(a) for a in absorbed])
    dropped = table["called"] & table["motif"].isin([m for a in absorbed for m in a])
    out = pd.concat([table[~dropped], scored[table.columns]], ignore_index=True)
    return out.sort_values(["called", "q_value"], ascending=[False, True], kind="stable")

# %% ../nbs/00_core.ipynb #3bfb4529
class TooManyCandidatesError(RuntimeError):
    """Raised when step 3 leaves more candidates than step 4 will compare.

    The candidate table is available as `.candidates` for inspection. A count this large
    usually means the thresholds are too loose for the sample, not that the strain has
    thousands of sites.
    """

    def __init__(self, n_candidates, max_candidates, log2fc_thr, score_thr, min_support, candidates):
        self.n_candidates = n_candidates
        self.max_candidates = max_candidates
        self.candidates = candidates
        super().__init__(
            f"Too many candidate motifs: {n_candidates} > max_candidates={max_candidates}. "
            f"Step 4 compares candidates with each other and would not finish. This usually "
            f"means the thresholds are too permissive for this sample: check that center=True, "
            f"or try a stricter flexible_motif_log2fc_thr (currently {log2fc_thr}, e.g. -1.0), "
            f"flexible_motif_score_thr (currently {score_thr}, e.g. 0.7), or "
            f"flexible_motif_min_support (currently {min_support}, e.g. 10). "
            f"Raise max_candidates only if you know why this strain has so many candidates. "
            f"Step 3's candidates are on this exception as `.candidates`."
        )

# %% ../nbs/00_core.ipynb #e7d6ec42
def find_restricted_motifs(log2fc_series,
                           left_context_str,
                           right_context_str,
                           n_jobs=1,
                           flexible_motif_patterns=None,
                           flexible_motif_log2fc_thr=-0.5,
                           flexible_motif_min_support=5,
                           flexible_motif_score_thr=0.5,
                           max_candidates=5000,
                           q_threshold=0.05,
                           encoded_library=None,
                           center=True
                           ):
    """The motifs one sample restricts: steps 2 to 4 and reporting on a log2FC series.

    The series is centred on its median; every pattern is scanned over the inserts with their
    flanks (step 2); the candidates are reduced to one description per site
    (`filter_redundant_patterns`, step 3) and cleared of those whose depletion a stronger
    candidate accounts for (`filter_explained_candidates`, step 4); the survivors are put on
    their canonical strand and scored (`annotate_significance`), and the called variants of a
    degenerate site are reported as one IUPAC motif (`merge_degenerate_calls`). Every test is against a
    GC-matched background: each plasmid's is the depletion rate of the plasmids in its insert-GC
    decile (`plasmid_background`), and a set of plasmids is tested against their mean.

    Args:
        log2fc_series (pd.Series): log2 fold change, indexed by insert sequence.
        left_context_str, right_context_str (str): the vector flanks of the insert.
        n_jobs (int): processes used to scan the patterns. 1 (default) runs in this process.
            A pattern takes about a second on a 30k-sequence library, so more is rarely worth
            the startup cost.
        flexible_motif_patterns (list): the shapes to search, as `(d1, spacer, d2)`.
            Defaults to `get_patterns()`. Each is rewritten to its `canonical_pattern` and
            duplicates dropped, so `(4, 4, 3)` is searched as `(3, 4, 4)` and never twice.
        flexible_motif_log2fc_thr (float): a plasmid counts as depleted below this, after
            centring. Default -0.5: low enough to see weakly restricting systems such as BREX,
            which a -1 threshold misses.
        flexible_motif_min_support (int): minimum plasmids for a motif to be considered. The
            default of 5 was set by a permutation test on the smaller example library: motifs
            with 3-4 supporting plasmids arose by chance about once per scan, none at 5 or above.
        flexible_motif_score_thr (float): at least this fraction of the plasmids carrying a
            candidate must be depleted, and a call must show it with confidence (the lower bound
            `fraction_depleted_lower` reaches it). Default 0.5, the value the draft's Fig 3 uses.
        max_candidates (int): the most candidates step 3 may hand to step 4, whose cost grows
            faster than their number. More raises `TooManyCandidatesError`, with the candidates
            attached. The default, 5000, is above the 3,144 that the busiest strain of the
            example data and the BB2 panel brings at the default thresholds.
        q_threshold (float): a motif is marked `called` when its Benjamini-Hochberg q-value,
            computed against its carriers' GC-matched background and over every motif the scan
            tested, falls below this. Motifs that miss it are still returned.
        encoded_library (tuple): `encode_library(get_lib_seq_context(log2fc_series.index,
            left_context_str, right_context_str))`, if the caller already has it. Strains
            screened with the same library and flanks share it, so a panel encodes it once.
            It must describe exactly `log2fc_series.index`, in order.
        center (bool): subtract the series' median before anything is thresholded, so that a
            sample shifted as a whole is held to the same stringency as any other.
            `avg_log2fc` is then relative to the sample's own typical plasmid.

    Returns:
        pd.DataFrame: one row per reported motif -- 'motif', 'fraction_depleted',
        'num_sequences', 'avg_log2fc', 'pattern', the columns `annotate_significance` adds, and
        'merged_from' -- called rows first.
    """
    if center:
        log2fc_series = log2fc_series - log2fc_series.median()
    candidates = pd.DataFrame(columns=['motif', 'fraction_depleted', 'num_sequences',
                                       'avg_log2fc', 'pattern'])
    report = functools.partial(annotate_significance, log2fc_thr=flexible_motif_log2fc_thr,
                               q_threshold=q_threshold, score_thr=flexible_motif_score_thr)
    if log2fc_series.empty:
        print("The input series is empty; there is nothing to scan.")
        return report(candidates, log2fc_series, left_context_str, right_context_str,
                      all_pvalues=np.array([])).assign(merged_from="")

    # The library is encoded once and every step below reads it.
    if encoded_library is None:
        encoded_library = encode_library(get_lib_seq_context(
            log2fc_series.index.tolist(), left_context_str, right_context_str))
    elif encoded_library[0].shape[0] != len(log2fc_series):
        raise ValueError(
            f"encoded_library holds {encoded_library[0].shape[0]} sequences but log2fc_series "
            f"has {len(log2fc_series)}; it must encode exactly this series' index, in order, "
            f"with these flanks.")
    fc = log2fc_series.to_numpy(dtype=float)
    background = plasmid_background(log2fc_series.index, fc, flexible_motif_log2fc_thr)

    if flexible_motif_patterns is None:
        flexible_motif_patterns = get_patterns()
    elif np.ndim(flexible_motif_patterns) == 1:          # one pattern rather than a list
        flexible_motif_patterns = [flexible_motif_patterns]
    # A pattern and its mirror find the same sites (the scan reads both strands), and a gapless
    # pattern is one run however it is split, so each is searched once, in canonical form.
    for p, c in sorted({(tuple(p), canonical_pattern(p)) for p in flexible_motif_patterns
                        if tuple(p) != canonical_pattern(p)}):
        print(f"Pattern {p} is searched as {c}: the same sites, read on the other strand.")
    flexible_motif_patterns = sorted({canonical_pattern(p) for p in flexible_motif_patterns},
                                     key=lambda x: (x[0] + x[2], x[1], x))

    # Step 2.
    worker = functools.partial(
        process_single_flexible_pattern, encoded_library=encoded_library,
        fc_values_for_flexible_analysis=fc, background=background,
        flexible_motif_log2fc_thr=flexible_motif_log2fc_thr,
        flexible_motif_score_thr=flexible_motif_score_thr,
        flexible_motif_min_support=flexible_motif_min_support)
    if n_jobs == 1:
        per_pattern = [worker(p) for p in tqdm(flexible_motif_patterns, desc="Scanning patterns")]
    else:
        # Each worker scans single-threaded: n_jobs processes each starting numba's thread pool
        # would ask for n_jobs x cores at once. imap keeps pattern order, so the result does not
        # depend on which worker finishes first.
        with Pool(processes=n_jobs) as pool:
            per_pattern = list(tqdm(pool.imap(functools.partial(worker, parallel=False),
                                              flexible_motif_patterns),
                                    total=len(flexible_motif_patterns), desc="Scanning patterns"))

    tested_pvalues = (np.concatenate([pv for _, pv, _ in per_pattern]) if per_pattern
                      else np.array([]))
    # The p-value a motif needs to be called: the largest that clears q_threshold over every
    # motif tested. Step 4 holds the candidates' leftovers to it, since they were selected
    # from that same pool.
    _q = benjamini_hochberg(tested_pvalues)
    scan_cutoff = tested_pvalues[_q < q_threshold].max() if (_q < q_threshold).any() else 0.0
    hits = [df for df, _, _ in per_pattern if not df.empty]
    totals = {p: t for p, (_, _, t) in zip(flexible_motif_patterns, per_pattern)}

    # Step 3, once over every pattern's candidates. It scores variants from the scan's counts,
    # so a pattern step 2 scanned is never rescanned.
    if hits:
        candidates = filter_redundant_patterns(
            pd.concat(hits, ignore_index=True), log2fc_series,
            left_context_str, right_context_str,
            log2fc_thr=flexible_motif_log2fc_thr, score_thr=flexible_motif_score_thr,
            min_support=flexible_motif_min_support, encoded=encoded_library, totals=totals,
            background=background)
        print(f"{sum(len(h) for h in hits)} candidate(s) across all patterns; "
              f"{len(candidates)} remain after step 3.")
    if len(candidates) > max_candidates:
        raise TooManyCandidatesError(len(candidates), max_candidates, flexible_motif_log2fc_thr,
                                     flexible_motif_score_thr, flexible_motif_min_support,
                                     candidates)

    # Step 4.
    candidates, explained = filter_explained_candidates(
        candidates, log2fc_series, left_context_str, right_context_str,
        log2fc_thr=flexible_motif_log2fc_thr, score_thr=flexible_motif_score_thr,
        min_support=flexible_motif_min_support, encoded=encoded_library,
        p_threshold=scan_cutoff, background=background)
    if explained:
        print(f"{len(explained)} candidate(s) whose score was borrowed:")
        for m, (by, n, s) in sorted(explained.items()):
            print(f"    {m} <- {by} (without them: n={n}, score={s:.2f})")

    # Canonicalise before printing, so the names in the log are the names in the table.
    candidates = _canonicalise_flexible_motifs(candidates)
    print(f"{len(candidates)} motif(s) reported.")
    for _, row in candidates.iterrows():
        print(f"  {row['motif']} (pattern {row['pattern']}), FracDep: {row['fraction_depleted']:.2f}, "
              f"AvgFC: {row['avg_log2fc']:.2f}, N: {row['num_sequences']}")
    table = report(candidates, log2fc_series, left_context_str, right_context_str,
                   all_pvalues=tested_pvalues, encoded=encoded_library, background=background)

    # A degenerate site's called variants, reported as one IUPAC motif.
    table = merge_degenerate_calls(
        table, log2fc_series, left_context_str, right_context_str, encoded_library, background,
        tested_pvalues, log2fc_thr=flexible_motif_log2fc_thr, q_threshold=q_threshold,
        score_thr=flexible_motif_score_thr, min_support=flexible_motif_min_support, totals=totals)
    merged = table[table["merged_from"] != ""]
    if len(merged):
        print(f"{len(merged)} degenerate site(s) reported as one motif:")
        for m, parts in zip(merged["motif"], merged["merged_from"]):
            print(f"  {m} <- {parts.replace('+', ' + ')}")
    return table
